    id: "sequences-cp-kadanes-algorithm",
    title: "Kadane's Algorithm: Maximum Subsegment Sum & Range Extraction in O(N)",
    slug: "sequences-cp-kadanes-algorithm",
    category: "Classic Algorithmic Techniques",
    subCategory: "Classic Techniques",
    language: "C++",
